// Collect all direct ytd-item-section-renderer children
const sections = Array.from(element.children).filter(
  el => el.tagName.toLowerCase() === 'ytd-item-section-renderer'
);
if (sections.length === 0) return;

// Separate into Shorts (contain grid-shelf-view-model) and others
const shortsSections = sections.filter(sec =>
  sec.querySelector('grid-shelf-view-model.ytGridShelfViewModelHost')
);
if (shortsSections.length === 0) return;

// Find the first non-Shorts section as the anchor insertion point
const firstNonShorts = sections.find(sec =>
  !sec.querySelector('grid-shelf-view-model.ytGridShelfViewModelHost')
);
if (!firstNonShorts) return;

// Determine if reordering is needed: check if any Shorts section comes after the first non-Shorts section
const allChildren = Array.from(element.children);
const firstNonShortsIdx = allChildren.indexOf(firstNonShorts);
const needsMove = shortsSections.some(sec => allChildren.indexOf(sec) > firstNonShortsIdx);
if (!needsMove) return;

// Insert all Shorts sections before the first non-Shorts section, preserving their relative order
shortsSections.forEach(sec => {
  element.insertBefore(sec, firstNonShorts);
});
